export function resolveHeartbeat(env: Record<string, string | undefined>, profile: { heartbeat?: number }, options: { heartbeat?: number }) {
  const ambient = Number(env.STREAM_HEARTBEAT ?? 41);
  const selected = options.heartbeat ?? profile.heartbeat ?? ambient;
  return Math.min(53, Math.max(11, selected));
}
